import {describe, expect, test} from "bun:test"

import {disassembleBocHex} from "../src/lib/disasm"

const EMBEDDED_DATA_BOC =
  "b5ee9c724101010100570000a9178d45190000000000000000402625a008011ac445debca569067cf73f05b9545361d0dd2c5bad6549bafb73bad27e85c7db00235888bbd794ad20cf9ee7e0b72a8a6c3a1ba58b75aca9375f6e775a4fd0b8fb44054e0b1389"
const TVM_CODE_BOC =
  ""

describe("disassembleBocHex", () => {
  test("identifies a single embedded slice as data", async () => {
    const result = await disassembleBocHex(EMBEDDED_DATA_BOC)

    expect(result.disasm.trim().startsWith("embed ")).toBe(true)
    expect(result.isEmbeddedData).toBe(true)
  })

  test("keeps actual TVM instructions available", async () => {
    const result = await disassembleBocHex(TVM_CODE_BOC)

    expect(result.disasm.trim().startsWith("SETCP 0")).toBe(true)
    expect(result.isEmbeddedData).toBe(false)
  })
})
